# ============================================================
# 037_Figure4_MainPanel_Objective4_v15.R
#
# OBJECTIVE 4 - MAIN FIGURE
#
# Panel A:
#   Cohen's kappa heatmap across the five behavioural
#   classification frameworks.
#
# Panel B:
#   Population composition (%) generated by each method.
#
# Panel C:
#   Behavioural distributions across the five previously
#   established cross-method consensus categories.
#
# IMPORTANT
# - This script does NOT recalculate any classification,
#   consensus category, agreement statistic, or behavioural score.
# - It reads only definitive objects already generated by
#   corrected Scripts 034 and 035.
# - No inferential statistic is recalculated.
# ============================================================


# ------------------------------------------------------------
# 0. Project directory
# ------------------------------------------------------------

project_root <- normalizePath(
  Sys.getenv(
    "LAPCOM_UCS_PROJECT_ROOT",
    unset = getwd()
  ),
  winslash = "/",
  mustWork = TRUE
)

if (!dir.exists(project_root)) {
  stop(
    "Project directory not found:\n",
    project_root
  )
}

setwd(project_root)


# ------------------------------------------------------------
# 1. Required packages
# ------------------------------------------------------------

required_packages <- c(
  "dplyr",
  "tidyr",
  "ggplot2",
  "patchwork"
)

missing_packages <- required_packages[
  !vapply(
    required_packages,
    requireNamespace,
    logical(1),
    quietly = TRUE
  )
]

if (length(missing_packages) > 0L) {
  stop(
    "Install the following packages before running this script:\n",
    paste(missing_packages, collapse = ", ")
  )
}

suppressPackageStartupMessages({
  library(dplyr)
  library(tidyr)
  library(ggplot2)
  library(patchwork)
})


# ------------------------------------------------------------
# 2. Directories
# ------------------------------------------------------------

objects_dir <- file.path(
  project_root,
  "03_Results",
  "Objects"
)

figures_dir <- file.path(
  project_root,
  "03_Results",
  "Figures"
)

if (!dir.exists(figures_dir)) {
  dir.create(
    figures_dir,
    recursive = TRUE
  )
}


# ------------------------------------------------------------
# 3. Definitive upstream objects
# ------------------------------------------------------------

kappa_file <- file.path(
  objects_dir,
  "objective4_kappa_matrix.rds"
)

method_size_file <- file.path(
  objects_dir,
  "objective4_five_method_size_table_long.rds"
)

profile_file <- file.path(
  objects_dir,
  "objective4_profile_data.rds"
)

required_input_files <- c(
  kappa_file,
  method_size_file,
  profile_file
)

missing_input_files <- required_input_files[
  !file.exists(required_input_files)
]

if (length(missing_input_files) > 0L) {
  stop(
    "The following definitive Objective 4 objects were not found:\n",
    paste(missing_input_files, collapse = "\n"),
    "\n\nRun the corrected Scripts 034 and 035 first."
  )
}


# ------------------------------------------------------------
# 4. Load definitive objects
# ------------------------------------------------------------

kappa_matrix <- readRDS(
  kappa_file
)

method_size_table <- readRDS(
  method_size_file
)

profile_data <- readRDS(
  profile_file
)


# ------------------------------------------------------------
# 5. Validate imported objects
# ------------------------------------------------------------

if (!is.matrix(kappa_matrix)) {
  stop(
    basename(kappa_file),
    " does not contain the expected matrix."
  )
}

if (!is.data.frame(method_size_table)) {
  stop(
    basename(method_size_file),
    " does not contain the expected data frame."
  )
}

if (!is.data.frame(profile_data)) {
  stop(
    basename(profile_file),
    " does not contain the expected data frame."
  )
}


expected_methods <- c(
  "Swaminathan",
  "PCA_Quantiles",
  "GMM",
  "TwoStep",
  "Louvain"
)

missing_kappa_methods <- setdiff(
  expected_methods,
  rownames(kappa_matrix)
)

missing_kappa_columns <- setdiff(
  expected_methods,
  colnames(kappa_matrix)
)

if (
  length(missing_kappa_methods) > 0L ||
  length(missing_kappa_columns) > 0L
) {
  stop(
    "The stored Cohen's kappa matrix does not contain all five ",
    "expected methods."
  )
}


required_size_columns <- c(
  "Method",
  "Classification",
  "n",
  "Percentage"
)

missing_size_columns <- setdiff(
  required_size_columns,
  names(method_size_table)
)

if (length(missing_size_columns) > 0L) {
  stop(
    "The stored method-size table is missing:\n",
    paste(missing_size_columns, collapse = ", ")
  )
}


required_profile_columns <- c(
  "Author",
  "ID",
  "Traceability_ID",
  "Behavioural_Index",
  "Swaminathan",
  "PCA_Quantiles",
  "GMM",
  "TwoStep",
  "Louvain",
  "n_Resilient",
  "n_Susceptible",
  "n_Intermediate",
  "Resilience_Consensus_Score",
  "Susceptibility_Consensus_Score",
  "Intermediate_Consensus_Score",
  "Consensus_Category",
  "distance_rz",
  "crossing_rz",
  "top_entry_rz",
  "top_time_rz"
)

missing_profile_columns <- setdiff(
  required_profile_columns,
  names(profile_data)
)

if (length(missing_profile_columns) > 0L) {
  stop(
    "The stored Objective 4 profile object is missing:\n",
    paste(missing_profile_columns, collapse = ", ")
  )
}

if (nrow(profile_data) != 89L) {
  stop(
    "The stored profile object does not contain the expected 89 ",
    "UCS-exposed zebrafish."
  )
}

if (anyDuplicated(profile_data$Traceability_ID) > 0L) {
  stop(
    "Duplicated Traceability_ID values were detected in ",
    basename(profile_file),
    "."
  )
}

if (
  anyNA(
    profile_data[
      c(
        "Consensus_Category",
        "distance_rz",
        "crossing_rz",
        "top_entry_rz",
        "top_time_rz"
      )
    ]
  )
) {
  stop(
    "Missing consensus labels or behavioural values detected in ",
    basename(profile_file),
    "."
  )
}


# ------------------------------------------------------------
# 6. Graphical order and labels
# ------------------------------------------------------------

method_order <- c(
  "Swaminathan",
  "PCA_Quantiles",
  "TwoStep",
  "Louvain",
  "GMM"
)

method_labels <- c(
  "Swaminathan" = "Swaminathan-like",
  "PCA_Quantiles" = "PCA-derived\nindex quantiles",
  "TwoStep" = "Two-Step",
  "Louvain" = "Louvain",
  "GMM" = "GMM"
)

consensus_order <- c(
  "Unanimous resilient",
  "High-consensus resilient",
  "Ambiguous/intermediate",
  "High-consensus susceptible",
  "Unanimous susceptible"
)

consensus_labels <- c(
  "Unanimous resilient" =
    "Unanimous\nresilient",
  "High-consensus resilient" =
    "High-consensus\nresilient",
  "Ambiguous/intermediate" =
    "Ambiguous/\nintermediate",
  "High-consensus susceptible" =
    "High-consensus\nsusceptible",
  "Unanimous susceptible" =
    "Unanimous\nsusceptible"
)


# ------------------------------------------------------------
# 7. Fixed graphical palette
# ------------------------------------------------------------

colour_turquoise <- "#63B8A6"
colour_coral <- "#F07A5A"
colour_grey_intermediate <- "grey78"
colour_resilient_high <- "#8FB7E8"
colour_susceptible_high <- "#F2B67E"

classification_colours <- c(
  "Resilient" = colour_turquoise,
  "Intermediate" = colour_grey_intermediate,
  "Susceptible" = colour_coral
)

consensus_colours <- c(
  "Unanimous resilient" =
    colour_turquoise,
  "High-consensus resilient" =
    colour_resilient_high,
  "Ambiguous/intermediate" =
    colour_grey_intermediate,
  "High-consensus susceptible" =
    colour_susceptible_high,
  "Unanimous susceptible" =
    colour_coral
)


# ------------------------------------------------------------
# 8. Panel A data - stored Cohen's kappa matrix
# ------------------------------------------------------------

kappa_display <- kappa_matrix[
  method_order,
  method_order,
  drop = FALSE
]

if (any(!is.finite(kappa_display))) {
  stop(
    "The stored Cohen's kappa matrix contains missing or non-finite ",
    "values in the required five-method comparison."
  )
}

panel_a_data <- as.data.frame(
  as.table(
    kappa_display
  ),
  stringsAsFactors = FALSE
) %>%
  dplyr::rename(
    Method_x = Var1,
    Method_y = Var2,
    Kappa = Freq
  ) %>%
  dplyr::mutate(
    Method_x = factor(
      Method_x,
      levels = method_order
    ),
    Method_y = factor(
      Method_y,
      levels = rev(method_order)
    ),
    Text_colour = ifelse(
      Kappa >= 0.60,
      "white",
      "black"
    )
  )


# ------------------------------------------------------------
# 9. Panel B data - stored method-size table
# ------------------------------------------------------------

panel_b_data <- method_size_table %>%
  dplyr::mutate(
    Method = as.character(Method),
    Classification = as.character(Classification)
  ) %>%
  dplyr::filter(
    Method %in% method_order
  ) %>%
  dplyr::mutate(
    Method = factor(
      Method,
      levels = method_order
    ),
    Classification = factor(
      Classification,
      levels = c(
        "Resilient",
        "Intermediate",
        "Susceptible"
      )
    ),
    Label = ifelse(
      n > 0,
      paste0(
        n,
        "\n(",
        format(
          round(
            Percentage,
            1
          ),
          nsmall = 1
        ),
        "%)"
      ),
      ""
    )
  )

if (
  nrow(panel_b_data) == 0L ||
  anyNA(panel_b_data$Method) ||
  anyNA(panel_b_data$Classification) ||
  any(!is.finite(panel_b_data$n)) ||
  any(!is.finite(panel_b_data$Percentage))
) {
  stop(
    "The stored method-size table could not be prepared for Panel B."
  )
}


# ------------------------------------------------------------
# 10. Panel C data - stored consensus classifications
# ------------------------------------------------------------

observed_consensus_labels <- unique(
  as.character(
    profile_data$Consensus_Category
  )
)

unexpected_consensus_labels <- setdiff(
  observed_consensus_labels,
  consensus_order
)

missing_consensus_labels <- setdiff(
  consensus_order,
  observed_consensus_labels
)

if (length(unexpected_consensus_labels) > 0L) {
  stop(
    "Unexpected consensus-category labels were found:\n",
    paste(unexpected_consensus_labels, collapse = ", ")
  )
}

if (length(missing_consensus_labels) > 0L) {
  stop(
    "Expected consensus-category labels were not found:\n",
    paste(missing_consensus_labels, collapse = ", ")
  )
}

profile_data <- profile_data %>%
  dplyr::mutate(
    Consensus_Category = factor(
      as.character(Consensus_Category),
      levels = consensus_order
    )
  )

consensus_counts <- profile_data %>%
  dplyr::count(
    Consensus_Category,
    name = "n"
  )

if (sum(consensus_counts$n) != 89L) {
  stop(
    "Consensus categories do not sum to 89 zebrafish."
  )
}


# ------------------------------------------------------------
# 11. Common theme
# ------------------------------------------------------------

theme_manuscript <- function() {
  ggplot2::theme_classic(
    base_size = 10.5,
    base_family = "Arial"
  ) +
    ggplot2::theme(
      axis.text = ggplot2::element_text(
        colour = "black"
      ),
      axis.title = ggplot2::element_text(
        colour = "black",
        size = 10.5
      ),
      axis.line = ggplot2::element_line(
        colour = "black",
        linewidth = 0.50
      ),
      axis.ticks = ggplot2::element_line(
        colour = "black",
        linewidth = 0.40
      ),
      plot.background = ggplot2::element_rect(
        fill = "white",
        colour = NA
      ),
      panel.background = ggplot2::element_rect(
        fill = "white",
        colour = NA
      ),
      plot.tag = ggplot2::element_text(
        face = "bold",
        size = 16
      ),
      plot.tag.position = c(
        0.12,
        1
      )
    )
}


# ------------------------------------------------------------
# 12. Build Panel A - Cohen's kappa heatmap
# ------------------------------------------------------------
# Publication-layout correction:
# - The heatmap remains a single ggplot.
# - The Cohen's kappa scale is drawn manually immediately to the
#   right of the 5 x 5 matrix, within the same coordinate system.
# - This avoids both excessive whitespace and overlap.
# - No agreement statistic is recalculated.
# ------------------------------------------------------------

# Numeric coordinates preserve square heatmap cells and allow the
# colour scale to be positioned precisely beside the matrix.
panel_a_plot_data <- panel_a_data %>%
  dplyr::mutate(
    x_num = match(
      as.character(Method_x),
      method_order
    ),
    y_num = match(
      as.character(Method_y),
      rev(method_order)
    )
  )

# Manual colour-bar geometry.
# The bar starts only 0.12 x-units to the right of the heatmap edge.
colourbar_bottom <- 1.45
colourbar_top <- 3.75
colourbar_xmin <- 5.64
colourbar_xmax <- 5.72

colourbar_breaks <- c(
  0,
  0.25,
  0.50,
  0.75,
  1
)

colourbar_edges <- seq(
  colourbar_bottom,
  colourbar_top,
  length.out = 201
)

panel_a_colourbar_data <- data.frame(
  xmin = colourbar_xmin,
  xmax = colourbar_xmax,
  ymin = colourbar_edges[-length(colourbar_edges)],
  ymax = colourbar_edges[-1],
  Kappa = seq(
    0,
    1,
    length.out = 200
  )
)

panel_a_colourbar_labels <- data.frame(
  Kappa = colourbar_breaks,
  y = colourbar_bottom +
    colourbar_breaks *
    (
      colourbar_top -
        colourbar_bottom
    ),
  label = sprintf(
    "%.2f",
    colourbar_breaks
  )
)

panel_a <- ggplot2::ggplot() +

  # Heatmap cells
  ggplot2::geom_tile(
    data = panel_a_plot_data,
    mapping = ggplot2::aes(
      x = x_num,
      y = y_num,
      fill = Kappa
    ),
    width = 1,
    height = 1,
    colour = "white",
    linewidth = 0.80
  ) +

  # Kappa values inside cells
  ggplot2::geom_text(
    data = panel_a_plot_data,
    mapping = ggplot2::aes(
      x = x_num,
      y = y_num,
      label = sprintf(
        "%.2f",
        Kappa
      ),
      colour = Text_colour
    ),
    family = "Arial",
    size = 3.45,
    show.legend = FALSE
  ) +

  ggplot2::scale_colour_identity() +

  # Manual colour bar placed immediately beside the matrix
  ggplot2::geom_rect(
    data = panel_a_colourbar_data,
    mapping = ggplot2::aes(
      xmin = xmin,
      xmax = xmax,
      ymin = ymin,
      ymax = ymax,
      fill = Kappa
    ),
    inherit.aes = FALSE,
    colour = NA
  ) +

  # Tick marks on the colour bar
  ggplot2::geom_segment(
    data = panel_a_colourbar_labels,
    mapping = ggplot2::aes(
      x = colourbar_xmax,
      xend = colourbar_xmax + 0.05,
      y = y,
      yend = y
    ),
    inherit.aes = FALSE,
    linewidth = 0.35,
    colour = "black"
  ) +

  # Numerical labels of the colour bar
  ggplot2::geom_text(
    data = panel_a_colourbar_labels,
    mapping = ggplot2::aes(
      x = colourbar_xmax + 0.08,
      y = y,
      label = label
    ),
    inherit.aes = FALSE,
    family = "Arial",
    size = 2.65,
    hjust = 0,
    colour = "black"
  ) +

  # Colour-bar title
  ggplot2::annotate(
    "text",
    x = (
      colourbar_xmin +
        colourbar_xmax
    ) / 2 + 0.30,
    y = colourbar_top + 0.38,
    label = "Cohen's \u03BA",
    family = "Arial",
    size = 3.05,
    hjust = 0.5
  ) +

  ggplot2::scale_fill_gradient(
    low = "white",
    high = colour_turquoise,
    limits = c(
      0,
      1
    ),
    guide = "none"
  ) +

  ggplot2::scale_x_continuous(
    breaks = 1:5,
    labels = unname(
      method_labels[
        method_order
      ]
    ),
    limits = c(
      0.50,
      6.35
    ),
    expand = c(
      0,
      0
    )
  ) +

  ggplot2::scale_y_continuous(
    breaks = 1:5,
    labels = unname(
      method_labels[
        rev(method_order)
      ]
    ),
    limits = c(
      0.50,
      5.50
    ),
    expand = c(
      0,
      0
    )
  ) +

  # Fixed coordinates keep the 5 x 5 heatmap cells square.
  ggplot2::coord_fixed(
    ratio = 1,
    clip = "off"
  ) +

  ggplot2::labs(
    tag = "A",
    x = NULL,
    y = NULL
  ) +

  theme_manuscript() +

  ggplot2::theme(
    axis.line = ggplot2::element_blank(),
    axis.ticks = ggplot2::element_blank(),

    axis.text.x = ggplot2::element_text(
      angle = 38,
      hjust = 1,
      vjust = 1,
      size = 8.8
    ),

    axis.text.y = ggplot2::element_text(
      size = 8.8
    ),

    plot.margin = ggplot2::margin(
      t = 4,
      r = 2,
      b = 2,
      l = 0
    )
  )


# ------------------------------------------------------------
# 13. Build Panel B - population partitions
# ------------------------------------------------------------
# FIXED MANUSCRIPT CONVENTION:
#   Resilient = TOP of each stacked bar (turquoise)
#   Intermediate = middle when present (grey)
#   Susceptible = BOTTOM of each stacked bar (coral)
#
# Factor order is Resilient -> Intermediate -> Susceptible and
# position_stack(reverse = FALSE) preserves this top-to-bottom
# convention in the displayed stack.

panel_b <- ggplot2::ggplot(
  panel_b_data,
  ggplot2::aes(
    x = Method,
    y = Percentage,
    fill = Classification
  )
) +
  ggplot2::geom_col(
    position = ggplot2::position_stack(
      reverse = FALSE
    ),
    width = 0.68,
    colour = "black",
    linewidth = 0.45
  ) +
  ggplot2::geom_text(
    ggplot2::aes(
      label = ifelse(
        n > 0,
        Label,
        ""
      )
    ),
    position = ggplot2::position_stack(
      vjust = 0.5,
      reverse = FALSE
    ),
    family = "Arial",
    size = 3.0,
    lineheight = 0.90,
    colour = "black"
  ) +
  ggplot2::scale_fill_manual(
    values = classification_colours,
    breaks = c(
      "Resilient",
      "Intermediate",
      "Susceptible"
    ),
    drop = FALSE,
    name = NULL
  ) +
  ggplot2::scale_x_discrete(
    labels = method_labels
  ) +
  ggplot2::scale_y_continuous(
    limits = c(
      0,
      100
    ),
    breaks = seq(
      0,
      100,
      by = 20
    ),
    labels = function(x) {
      paste0(
        x,
        "%"
      )
    },
    expand = ggplot2::expansion(
      mult = c(
        0,
        0
      )
    )
  ) +
  ggplot2::labs(
    tag = "B",
    x = NULL,
    y = "Population occupancy"
  ) +
  theme_manuscript() +
  ggplot2::theme(
    axis.text.x = ggplot2::element_text(
      size = 8.5,
      lineheight = 0.90
    ),
    axis.title.y = ggplot2::element_text(
      margin = ggplot2::margin(
        r = 7
      )
    ),
    legend.position = "top",
    legend.justification = "center",
    legend.direction = "horizontal",
    legend.box = "horizontal",
    legend.text = ggplot2::element_text(
      size = 8.5
    ),
    legend.key.size = grid::unit(
      0.36,
      "cm"
    ),
    plot.margin = ggplot2::margin(
      t = 10,
      r = 8,
      b = 4,
      l = 8
    )
  )


# ------------------------------------------------------------
# 14. Deterministic jitter positions for Panel C
# ------------------------------------------------------------

jitter_seed <- 2026L
jitter_width <- 0.075

profile_data <- profile_data %>%
  dplyr::mutate(
    Consensus_x = as.numeric(
      Consensus_Category
    )
  )

set.seed(
  jitter_seed
)

profile_data <- profile_data %>%
  dplyr::mutate(
    Jitter_x = Consensus_x +
      stats::runif(
        dplyr::n(),
        min = -jitter_width,
        max = jitter_width
      )
  )


# ------------------------------------------------------------
# 15. Panel C helper - Figure 2 Mahalanobis visual grammar
# ------------------------------------------------------------

make_consensus_violin <- function(
  variable_name,
  variable_label,
  show_y_title = FALSE,
  add_panel_tag = FALSE
) {

  current_plot <- ggplot2::ggplot() +

    ggplot2::geom_hline(
      yintercept = 0,
      linetype = "dashed",
      colour = "grey50",
      linewidth = 0.45
    ) +

    ggplot2::geom_violin(
      data = profile_data,
      mapping = ggplot2::aes(
        x = Consensus_x,
        y = .data[[variable_name]],
        group = Consensus_Category,
        fill = Consensus_Category,
        colour = Consensus_Category
      ),
      width = 0.78,
      trim = TRUE,
      alpha = 0.20,
      linewidth = 0.75,
      show.legend = FALSE